$ErrorActionPreference='Stop'
Set-Location 'C:\Users\Xxkan\mhw-mods'
$origin=(git remote get-url origin)
if($origin -notmatch 'fengie/mhw-mods'){throw "Unexpected origin: $origin"}
git fetch origin --prune
if($LASTEXITCODE -ne 0){throw 'fetch failed'}
$base=(git rev-parse origin/main).Trim()
$gov=@('AGENTS.md','GLOBAL_GIT_DIRECTIVE.md','NEXT-AGENT-START-HERE.md','_AGENT_CONTEXT/CURRENT_REVISION.json','_AGENT_CONTEXT/CONTINUITY_PROTOCOL.md','_AGENT_CONTEXT/LEARNED_RULES.md','_AGENT_CONTEXT/README_FIRST.md')
foreach($f in $gov){git cat-file -e "origin/main:$f" 2>$null;if($LASTEXITCODE -ne 0){throw "missing on origin/main: $f"};git show "origin/main:$f" *> $null}
$current=(git branch --show-current).Trim()
$wt=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach($line in (git worktree list --porcelain)){if($line -like 'branch refs/heads/*'){[void]$wt.Add($line.Substring(18))}}
gh auth status *> $null
if($LASTEXITCODE -ne 0){throw 'gh auth unavailable'}
$open=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach($p in ((gh pr list --repo fengie/mhw-mods --state open --limit 200 --json headRefName,number,title | ConvertFrom-Json))){if($p.headRefName){[void]$open.Add([string]$p.headRefName)}}
$prot=@{}
foreach($b in ((gh api --method GET 'repos/fengie/mhw-mods/branches?per_page=100' | ConvertFrom-Json))){$prot[[string]$b.name]=[bool]$b.protected}
function Safe([string]$name,[string]$ref,[bool]$remote){
  if($name -eq 'main' -or $name -like 'release/*' -or $name -eq 'heaven-bridge'){return $false}
  if($wt.Contains($name)){return $false}
  if((-not $remote) -and $name -eq $current){return $false}
  if($open.Contains($name)){return $false}
  if($remote -and $prot.ContainsKey($name) -and $prot[$name]){return $false}
  $ahead=[int](git rev-list --count "origin/main..$ref")
  if($ahead -eq 0){return $true}
  $ch=@(git cherry origin/main $ref)
  if($LASTEXITCODE -ne 0){return $false}
  return -not [bool](@($ch|Where-Object{$_ -like '+ *'}).Count)
}
$localBefore=@(git for-each-ref --format='%(refname:strip=2)' refs/heads | Where-Object{$_ -and $_ -ne 'main'} | Sort-Object -Unique)
$remoteBefore=@(git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object{$_ -and $_ -ne 'HEAD' -and $_ -ne 'main'} | Sort-Object -Unique)
git fetch origin --prune *> $null
$base=(git rev-parse origin/main).Trim()
$deletedLocal=@()
foreach($b in $localBefore){if(Safe $b $b $false){git branch -D -- $b *> $null;if($LASTEXITCODE -eq 0){$deletedLocal+=$b}}}
$deletedRemote=@()
$fail=@()
foreach($b in $remoteBefore){
  git show-ref --verify --quiet "refs/remotes/origin/$b"
  if($LASTEXITCODE -ne 0){continue}
  if(Safe $b "origin/$b" $true){
    $o=(git push origin --delete $b 2>&1)
    if($LASTEXITCODE -eq 0){$deletedRemote+=$b}else{$fail+="$b :: $($o -join ' | ')"}
  }
}
$prune=(git fetch origin --prune 2>&1)
$remoteAfter=@(git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object{$_ -and $_ -ne 'HEAD' -and $_ -ne 'main'} | Sort-Object -Unique)
$localAfter=@(git for-each-ref --format='%(refname:strip=2)' refs/heads | Where-Object{$_ -and $_ -ne 'main'} | Sort-Object -Unique)
$pres=@()
foreach($b in $remoteAfter){
  $ahead=[int](git rev-list --count "origin/main..origin/$b")
  $reason='contains unique/non-equivalent commits'
  if($b -like 'release/*'){$reason='release branch retained by policy'}
  elseif($b -eq 'heaven-bridge'){$reason='Heaven Local Bridge infrastructure'}
  elseif($wt.Contains($b)){$reason='checked out in local worktree'}
  elseif($open.Contains($b)){$reason='open PR / active work'}
  elseif($prot.ContainsKey($b) -and $prot[$b]){$reason='protected branch'}
  $pres+="$b :: ahead=$ahead :: $reason"
}
[ordered]@{
 origin_main_sha=$base
 current_branch=$current
 local_before=1+$localBefore.Count
 remote_before=1+$remoteBefore.Count
 deleted_local=$deletedLocal
 deleted_remote=$deletedRemote
 preserved=$pres
 delete_failures=$fail
 stale_refs_pruned=($LASTEXITCODE -eq 0)
 final_local_count=1+$localAfter.Count
 final_remote_count=1+$remoteAfter.Count
 final_local=@('main')+$localAfter
 final_remote=@('main')+$remoteAfter
 no_known_unique_work_destroyed=($fail.Count -eq 0)
}|ConvertTo-Json -Depth 6
